def max_score(duration, initial_diffs):
    max_diffs = [(time_diff, -((-time_diff))) for time_diff in initial_diffs if time_diff >= 0]
    if not max_diffs:
        return duration * 500
    time_diffs = sorted([-diff for _, diff in max_diffs])
