    x, y = soldier
    dx, dy = direction
    for _ in range(abs(dx | dy)):
        next_x, next_y = x + dx, y + dy
        if next_x < 0 or next_x >= len(battlefield) or next_y < 0 or next_y >= len(battlefield[0]):
