from collections import deque

def f(s):
    r = []
    for c in s:
        if c.isalpha():
            r.append(c)
        else:
            try: 
                r.pop()
            except IndexError:
                return "Crashed"
    return "".join(r)

def solve(s, t):
    r_deque = deque(t)
    min_deletions = len(s) - len(f(s))

    for i, s_char in enumerate(s):
        if s_char != '.':
            r_deque.append(s_char)
            if len(r_deque) > len(t):
                r_deque.popleft()
            continue
        curr_back_index = r_deque.index(t[-(i+1)])
        end_back_index = max(curr_back_index - len(t), -len(t))

        if min_deletions > end_back_index - curr_back_index - 1:
            min_deletions = end_back_index - curr_back_index - 1
            r_deque = r_deque[curr_back_index:]

    return min_deletions

