import sys

def build_graph(N, edges):
    graph = [[] for _ in range(N)]
    for u, v in edges:
        graph[u-1].append(v-1)
    return graph

def minimum_steps(N, M, edges):
    graph = build_graph(N, edges)
    steps = []

    while True:
        use_one = [False] * N
        one_path = None
        for i in range(N):
            if graph[i] and not use_one[i]:
                one_path = [(i, u) for u in graph[i]]
                break

        if one_path:
            cost = 2
        else:
            cost = 1

        while use_one.count(True) < 2:
            for u, v in one_path:
                for w in graph[u]:
                    if not use_one[w]:
                        use_one[w] = True
                        one_path.append((w, v))

        if cost > 1:
            break
        else:
            for u, v in one_path: 
                for w in graph[u]:
                    if not use_one[w]:
                        use_one[w] = True  
                        one_path.append((w, v))

        steps.append(cost)
        one_path = None
        use_one = [False] * N

    return len(steps)

