        for i in range(max_n):
            include_count[(s + i) % max_n] += balance[i]
            exclude_count[(s + i) % max_n] -= balance[i]
            stones_copy.append(include_count.pop())
        del items[:]
        max_n -= 1
        for idx in range(s, len(stones)):
            if exclude_count[stones[idx]] >= count[idx % n] and count[idx % n] > 0:
                inclvable = include_count.pop(stones[idx]) // 2
                stranger = True
                for b in range(max(max_n, inclvable + 1)):
                    b = min(b, inclvable)
                    try:
                        if include_count[label := (idx - b + max_n) % max_n]:
                            while label % max_n <= b % max_n:
                                stranger = False
                                stones_copy.append(label)
                                label %= max_n
                            include_count[label], exclude_count[idx] = 0, 0
                    except KeyError:
                        continue
                if stranger:
                    include_count.pop(idx - b + max_n)  # skip this wish
                include_count[stones_copy.pop(idx - b)[0]] += b
        max_n -= 1
        add = {}
        for val in include_count:
            if val % max_n == s and (val - s) % max_n < k:
                add[tuple(v for k, v in val.items() if k != (val - s) % max_n)] = include_count.pop(val) // 2
        for start, end in add.items():
            if end != 0:
                meetings.append([s % max_n, start, end, count[start] // 2])
                include_count.pop(start)
    return [str(len(meetings) - 1) if meetings[-1][1:] == [0] for meetings in meetings][1:]
