def toy_soldier_game(n, m, k, battlefield):
    """
    Determine the winner of the Toy Soldier game.
    Shrek attacks, Donkey retreats, the first player makes a move.
    """
    first_player_move = True
    k = 1

    while True:
        # Shrek's turn
        if first_player_move:
            # Attack logic
            for i in range(n):
                for j in range(m):
                    if battlefield[i][j] == 'G':
                        # Attack logic with multiple elements to explore different directions
                        for d in range(1, k+1):
                            x, y = min(i, j), max(i, j)
                            for dx, dy in (0, 1), (0, -1), (-1, 0), (1, 0):
                                new_x, new_y = x + dx*d, y + dy*d
                                if 0 <= new_x < n and 0 <= new_y < m and battlefield[new_x][new_y] == 'R':
                                    battlefield[i][j] = battlefield[new_x][new_y] = '-'
                                    battlefield[new_x][new_y] = battlefield[i][j] = 'X'
                                    break

        # Donkey's turn
        else:
            # Retreat logic
            for i in range(n):
                for j in range(m):
                    if battlefield[i][j] == 'R':
                        directions = [(0, 1), (0, -1), (-1, 0), (1, 0)]
                        for dx, dy in directions:
                            new_x, new_y = i + dx*k, j + dy*k
                            if 0 <= new_x < n and 0 <= new_y < m and battlefield[new_x][new_y] in ['G', '-']:
                                new_count, new_idx = str.count(str(battlefield[new_x][new_y]), battlefield[min(i, j)][min(i, j)])
                                if 1 <= new_count <= k:
                                    continue
        first_player_move = not first_player_move

        # Check for draw
        if '-' * k * n in ''.join(line for line in battlefield):
            return "Draw"
        # Check for winner
        g_count, r_count = str.count(str(battlefield), 'G'), str.count(str(battlefield), 'R')
        if g_count > r_count:
            return "Second"
        elif g_count < r_count:
            return "First"
        else:
            return "Second"

