import sys

def solve(n, s, m, r, mi, ri, li, ri, ti):
    if ti == 0:
        mana = mi * (mi - 1)
    else:
        mana = r * ((mi + 1) * (2 * ri - mi + 1) + 2 * ri)
        if ti % r == 0:
            mana += (ri - (mi + 1))
    return mana

def preprocess(s, m, r):
    fib = {0: 0, 1: 1}
    for i in range(2, 116):  # approximation for logarithm
        fib[i] = (fib[i-1] + fib[i-2]) % m
    pi = [s, r, s - m]  # can be used to keep previous mana per pony
    for i in range(2, 116):
        pi.append((pi[i-1] + pi[i-2]) % m)
    return fib, pi

def main():
