class BitBucket:
    def __init__(self, m: int) -> None:
        self.bit = [0] * m
        self.use = [False] * m

    def push(self, i: int) -> bool:
        if self.use[i] or not self.bit[i]: 
            return False
        if self.bit[(i-1) & self.bit[~i]]: 
            self.use[i] = True
            self.bit[i] = (i+1) & self.bit[~i]
            return True

        self.use[i] = True
        self.bit[i] = _o
        return True

class Boboniu:
    def __init__(self, id: int, lang: str) -> None:
        self.id = id
        self.atcoder = lang == 'AtCoder'

    def __fetch(self, cs: bytes) -> Tuple[str, bool]:
        i = cs.find(b"/")
        return cs[:i+1].decode("utf8"), cs[(i-2):i-1:],
    def __account_id(self, v: Tuple[str, bool]) -> int:
        return v[1] + (1 << 31) if v[0] == "atcoder" else v[1]
    def __process(self, cs: bytes):
        l, *cs = map(int,cs)
        b = (105 - sorted(map(lambda i: i & 0x10E if i & 0x903 else i, cs))[-1] >> 5) ^ l 
        return (b, *map(lambda i: i & 0x989 if i & 0x903 else i, cs), l&~b)
    def preprocess(self, cs: bytes):
        return [(cs[0],), "XX"], cs[1:]
    def __scramble(self, cs: bytes) -> str:
        o = Op(cs[1:], "AtCoder" if self.atcoder else False)
        j = jfunc[cs[0]]
        return str(o.j(j(cs[1:], o.reverse()))) + str(o.v/o.one(l)),

class Op:
    def __init__(so: self, t: bytes) -> None: 
        so.t, so.op, so.reverse = self.__fetch(t)

    def j(so: self, j: Callable=None) -> bytes:
        if j is None: 
            op = BitBucket(len(so.t))
            ys = [so.t]
            for n in so.t: 
                m = op.push(ys.pop() * n)
                if m is True: 
                    ys.insert(N, op.bit.pop())
        return so.op.so(*ys), op
