def get_dss(graph):
    ds = [0]*len(graph)
    letters = [False]*len(graph)
    dss_map = defaultdict(list)
    min_distance = 100000
    calc_n = -1
    for x in range(1, len(graph)):
        letter_used = 0
        for s in graph[x]:
            if min_distance > (s[0] - x) ** 2 - 2 * s[1] * s[1]:
                min_distance = (s[0] - x) ** 2 - 2 * s[1] * s[1]
                calc_n = x
                letter_used = 0
                break
            else:
                letter_used = max(letter_used, 2 - letter_used)   
                letters[x] = letters[s[1]] = (letter_used+1)%2

        for s in graph[x]:
            if s[1] == x:
                continue

            detail = min_distance + (s[0] - x) ** 2
            letters[x] = letters[s[1]] = (letter_used+1)%2

            if letters[x] == letters[s[1]] or (letters[s[1]]+letters[x]) % 2 == 0 or letters[s[1]] == 0:
                detail += 2
            dss = detail + s[1] * (s[1]+1)//2
            ds[x] += dss
            dss_map[s[1]].append((s[1], x, min_distance))

    for x in range(1, len(graph)):
        if letters[x] == 0:
            continue
        dss = 0
        for x2 in graph[x][1:]:
            detail = (min_distance + x2[0] ** 2 - 2 * x2[1] * x2[1])
            dss_map[x2[1]].append((x2[1], x, detail))
            dss += detail

        if dss == 0:
            continue

        ds[x] = dss if (dss_map[x][0][1] < dss_map[x2[1]][0][1]) else dss + (x - x2[0] + 1) * min_distance

    return sorted(dss_map)

