        dan += (((k-1) % fours+3)%fours+3) * d
        return k * c + d * c * d * ( (k-2) // fours ) * ( (k-fours) // 2 ) 

    dss = sorted(get_dss(graph))

    picked = []
    cnt = 0
    dss_instances = dss.pop()

